import { DEFAULT_NEW_GAME_SETUP } from '../../src/presentation/new-game';
import { generateOpeningLife, prepareOpeningLife } from '../../src/presentation/opening-life';
import { searchLifePlaces } from '../../src/simulation/index';
import { createWorld } from '../../src/simulation/world';
import { personName } from '../../src/simulation/people';
import { principlePullsOf, principlesFromPulls } from '../../src/simulation/principles-from-life';
import { ensureOfficeholderPrinciples, principledLeaning } from '../../src/simulation/governing/officeholder-principles';
const place=searchLifePlaces('',1,{stateJurisdictionKey:'US-OR',scope:'locality'})[0]!;
const seed='officeholder-principles-US-OR';
const game=generateOpeningLife(prepareOpeningLife({...DEFAULT_NEW_GAME_SETUP,seed,placeKey:place.key,startAge:40,questionnaire:'skipped'})).game!;
const world=createWorld({seed:game.world.seed,lineage:'production',control:game.world.control,currentDate:game.world.currentDate,people:game.world.personOrder.map(id=>game.world.people[id]!),jurisdictions:game.world.jurisdictionOrder.map(id=>game.world.jurisdictions[id]!),policyCatalog:game.world.policyCatalog});
const before=JSON.stringify(world);
const held=new Set(world.history.principles.map(r=>r.personId));
const ids=world.personOrder.filter(id=>id!==game.playerPersonId&&!held.has(id)&&principlesFromPulls(world,id,principlePullsOf(world,id)).length>0).slice(0,12);
const next=ensureOfficeholderPrinciples(world,ids);
let example:unknown=null;
for(const id of ids){
 for(const pid of next.policyCatalog.propositionOrder){
  const leaning=principledLeaning(next,id,pid);
  if(!leaning.score)continue;
  const rows=next.history.principles.filter(r=>leaning.recordIds.includes(r.id));
  example={personId:id,name:personName(world.people[id]!),proposition:next.policyCatalog.propositions[pid],leaning,rows,pulls:principlePullsOf(world,id)};break;
 }
 if(example)break;
}
const unsupported=world.personOrder.find(id=>id!==game.playerPersonId&&principlesFromPulls(world,id,principlePullsOf(world,id)).length===0)!;
console.log(JSON.stringify({head:'76e29c3a4715eef2d21ee10326fc2f6267eb9608',seed,place,date:world.currentDate,selectedPeople:ids.length,newRows:next.history.principles.length-world.history.principles.length,inputUnchanged:before===JSON.stringify(world),idempotent:ensureOfficeholderPrinciples(next,ids)===next,unsupported:{personId:unsupported,name:personName(world.people[unsupported]!),sameWorld:ensureOfficeholderPrinciples(world,[unsupported])===world},example},null,2));
